// Example checklist for adding and clearing items in a list

const checklist = {
  items: [],
  addItem(item) {
    this.items.push(item);
  },
  clearItems() {
    this.items = [];
  }
};

// Usage example
checklist.addItem('Task 1');
checklist.addItem('Task 2');
console.log(checklist.items); // Output: ['Task 1', 'Task 2']
checklist.clearItems();
console.log(checklist.items); // Output: []

